// Fetch both topics' plain-text extracts through the CORS-enabled API.
const FIXTURES = {
  Volcano: 'A volcano is a rupture in the crust of a planetary-mass object that ' +
    'allows hot lava, volcanic ash, and gases to escape from a magma chamber below ' +
    'the surface. Eruptions can create lava flows, ash clouds and pyroclastic ' +
    'density currents. Volcanoes are most often found where tectonic plates are ' +
    'diverging or converging. The eruption of magma builds stratovolcanoes, shield ' +
    'volcanoes and cinder cones, and volcanic activity shapes crust on other ' +
    'planets and moons as well.',
  Glacier: 'A glacier is a persistent body of dense ice that is constantly moving ' +
    'downhill under its own weight. A glacier forms where the accumulation of snow ' +
    'exceeds its ablation over many years. Glaciers slowly deform and flow, carving ' +
    'cirques, moraines and fjords. Glacier ice is the largest reservoir of fresh ' +
    'water on Earth, and the study of glaciers is called glaciology. Ice sheets, ' +
    'ice caps and valley glaciers respond strongly to climate.',
};

async function fetchExtract(title) {
  const url = 'https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*' +
    '&prop=extracts&explaintext=1&exchars=8000&redirects=1&titles=' +
    encodeURIComponent(title);
  const res = await fetch(url);
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const data = await res.json();
  const pages = data.query.pages;
  const page = pages[Object.keys(pages)[0]];
  if (!page.extract) throw new Error('no such article: ' + title);
  return { title: page.title, text: page.extract, live: true };
}

const a = String(nb.get('wiki_topic_a') || 'Volcano');
const b = String(nb.get('wiki_topic_b') || 'Glacier');

let result;
try {
  const [ea, eb] = await Promise.all([fetchExtract(a), fetchExtract(b)]);
  result = { a: ea, b: eb };
} catch (err) {
  console.warn('live fetch failed (' + err.message + ') - using bundled fixtures');
  result = {
    a: { title: 'Volcano', text: FIXTURES.Volcano, live: false },
    b: { title: 'Glacier', text: FIXTURES.Glacier, live: false },
  };
}

for (const key of ['a', 'b']) {
  const e = result[key];
  console.log((e.live ? 'LIVE ' : 'FIXTURE ') + e.title + ': ' + e.text.length +
    ' chars - "' + e.text.slice(0, 90).replace(/\s+/g, ' ') + '…"');
}
nb.set('wiki_texts', result);
return { a: result.a.title, b: result.b.title, live: result.a.live };
